<?php namespace App\Http\Controllers;
use App\Models\{Entry,Source,Submission,ImportRun}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Str;
class AdminController {
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);if(Auth::attempt($v+['is_admin'=>true])){$r->session()->regenerate();return redirect('/admin');}return back()->withErrors(['email'=>'Invalid administrator credentials.']);}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/admin/login');}
 public function dashboard(){return view('admin',['entries'=>Entry::latest()->paginate(30,['*'],'entries'),'sources'=>Source::latest()->get(),'submissions'=>Submission::latest()->paginate(20,['*'],'submissions'),'runs'=>ImportRun::latest()->limit(20)->get()]);}
 public function entry(Request $r,?Entry $entry=null){$v=$r->validate(['type'=>'required|in:job,scholarship,event,news,directory','title'=>'required|string|max:255','title_bn'=>'nullable|string|max:255','summary'=>'nullable|string|max:10000','country'=>'nullable|string|max:100','category'=>'nullable|string|max:100','city'=>'nullable|string|max:100','url'=>'required|url:http,https|max:2048','status'=>'required|in:pending,published,rejected','deadline'=>'nullable|date','event_start'=>'nullable|date','expires_at'=>'nullable|date']);if($entry){if($entry->url!==$v['url'])$v+=['link_checked_at'=>null,'link_status'=>null,'verified_at'=>null];$entry->update($v);}else Entry::create($v+['slug'=>Str::limit(Str::slug($v['title']),150,'').'-'.Str::lower(Str::random(10)),'fingerprint'=>hash('sha256',Str::uuid()->toString())]);return redirect('/admin')->with('success','Entry saved');}
 public function source(Request $r,?Source $source=null){$v=$r->validate(['name'=>'required|string|max:150','driver'=>'required|in:rss,adzuna','type'=>'required|in:job,scholarship,event,news','url'=>'required|url:https|max:2048','country'=>'nullable|string|max:100','interval_minutes'=>'required|integer|min:60|max:10080','enabled'=>'nullable|boolean']);$v['enabled']=$r->boolean('enabled');if($v['driver']==='adzuna'&&($v['type']!=='job'||!preg_match('/^[a-z]{2}$/D',$v['country']??'')))return back()->withErrors(['country'=>'Adzuna requires job type and two-letter country code.']);if($source)$source->update($v);else Source::create($v);return back()->with('success','Source saved');}
 public function verify(Entry $entry){abort_unless($entry->type==='directory',404);$entry->update(['verified_at'=>now()]);return back()->with('success','Editorial review recorded');}
 public function submission(Request $r,Submission $submission){$submission->update($r->validate(['status'=>'required|in:pending,reviewed,rejected']));return back();}
}
